// Runtime behaviour shared by the English page (/) and the pre-rendered Arabic page (/ar/).
// Page content lives in the HTML; the Arabic page is generated by tools/build-ar.mjs.

const html = document.documentElement;
const isAr = html.lang === "ar";

const UI = isAr
  ? {
      toLight: "التبديل إلى الوضع الفاتح",
      toDark: "التبديل إلى الوضع الداكن",
      menuOpen: "فتح القائمة",
      menuClose: "إغلاق القائمة",
      copied: "تم نسخ البريد الإلكتروني ✓",
      copyFail: "تعذّر النسخ. البريد: riad.b.baytamouni@gmail.com",
    }
  : {
      toLight: "Switch to light mode",
      toDark: "Switch to dark mode",
      menuOpen: "Open menu",
      menuClose: "Close menu",
      copied: "Email copied ✓",
      copyFail: "Couldn't copy. Email: riad.b.baytamouni@gmail.com",
    };

// ================= Theme =================
// The initial theme is set by the inline script in <head> (saved choice, else system preference).
const themeToggle = document.getElementById("themeToggle");

function syncThemeButton() {
  const dark = html.dataset.theme !== "light";
  themeToggle.setAttribute("aria-label", dark ? UI.toLight : UI.toDark);
  document.querySelector('meta[name="theme-color"]').content = dark ? "#0b1220" : "#f7f9fc";
}
syncThemeButton();

themeToggle.addEventListener("click", () => {
  html.dataset.theme = html.dataset.theme === "light" ? "dark" : "light";
  try { localStorage.setItem("theme", html.dataset.theme); } catch { /* storage blocked */ }
  syncThemeButton();
});

// ================= Language link keeps the current section =================
const langToggle = document.getElementById("langToggle");
langToggle.addEventListener("click", () => {
  if (location.hash) langToggle.href = langToggle.getAttribute("href").split("#")[0] + location.hash;
});

// ================= Mobile menu (sheet, Esc to close, focus trap) =================
const menuToggle = document.getElementById("menuToggle");
const navLinks = document.getElementById("navLinks");
const mobileQuery = window.matchMedia("(max-width: 860px)");

function setMenu(open, { focusButton = false } = {}) {
  navLinks.classList.toggle("open", open);
  document.body.classList.toggle("menu-open", open);
  menuToggle.setAttribute("aria-expanded", String(open));
  menuToggle.setAttribute("aria-label", open ? UI.menuClose : UI.menuOpen);
  if (open) navLinks.querySelector("a").focus();
  else if (focusButton) menuToggle.focus();
}

menuToggle.addEventListener("click", () => setMenu(!navLinks.classList.contains("open")));
navLinks.addEventListener("click", (e) => { if (e.target.closest("a")) setMenu(false); });
mobileQuery.addEventListener("change", () => setMenu(false));

document.addEventListener("keydown", (e) => {
  if (!navLinks.classList.contains("open")) return;
  if (e.key === "Escape") { setMenu(false, { focusButton: true }); return; }
  if (e.key !== "Tab") return;
  // Keep focus inside the open menu and its toggle button.
  const items = [menuToggle, ...navLinks.querySelectorAll("a")];
  const first = items[0], last = items[items.length - 1];
  if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
  else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
});

// ================= Active section highlight in nav =================
const navMap = new Map(
  [...navLinks.querySelectorAll('a[href^="#"]')].map((a) => [a.getAttribute("href").slice(1), a])
);
const sectionObserver = new IntersectionObserver(
  (entries) => {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      navMap.forEach((a) => a.removeAttribute("aria-current"));
      const link = navMap.get(entry.target.id);
      if (link) link.setAttribute("aria-current", "true");
    });
  },
  { rootMargin: "-45% 0px -50% 0px" }
);
document.querySelectorAll("main section[id]").forEach((s) => sectionObserver.observe(s));

// ================= Scroll reveal (content stays visible without JS; see .js in CSS) =================
const revealObserver = new IntersectionObserver(
  (entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add("visible");
        revealObserver.unobserve(entry.target);
      }
    });
  },
  { rootMargin: "0px 0px -10% 0px" }
);
document.querySelectorAll(".reveal").forEach((el) => revealObserver.observe(el));

// ================= Project filter =================
const filters = document.querySelectorAll(".filter");
const personalCards = document.querySelectorAll("#personalGrid .card");
filters.forEach((btn) => {
  btn.addEventListener("click", () => {
    const f = btn.dataset.filter;
    filters.forEach((b) => {
      const on = b === btn;
      b.classList.toggle("is-active", on);
      b.setAttribute("aria-pressed", String(on));
    });
    personalCards.forEach((card) => {
      card.hidden = f !== "all" && !card.dataset.cat.split(" ").includes(f);
      card.classList.add("visible");
    });
  });
});

// ================= Toast + copy email =================
const toast = document.getElementById("toast");
let toastTimer;
function showToast(msg) {
  toast.textContent = msg;
  toast.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove("show"), 2400);
}

document.getElementById("copyEmail").addEventListener("click", async () => {
  try {
    await navigator.clipboard.writeText("riad.b.baytamouni@gmail.com");
    showToast(UI.copied);
  } catch {
    showToast(UI.copyFail);
  }
});

// ================= Footer year =================
document.getElementById("year").textContent = new Date().getFullYear();
